const records = readLines('input/links.csv')
  .slice(1)
  .map((line, index) => {
    const [source, destination] = line.split(',').map(Number);
    return { source, destination, line: index + 2 };
  });
const pageIndex = new Map(input.pages.map((page, index) => [page.id, index]));
const edges: Edge[] = [];
const ignored: GraphData['ignored'] = [];
const ignoredCounts = { unknown: 0, self: 0, duplicate: 0 };
const accepted = new Set<string>();
for (const record of input.records) {
  const key = `${record.source},${record.destination}`;
  let reason: IgnoreReason | null = null;
  if (!pageIndex.has(record.source) || !pageIndex.has(record.destination)) reason = 'unknown';
  else if (record.source === record.destination) reason = 'self';
  else if (accepted.has(key)) reason = 'duplicate';
  if (reason !== null) {
    ignored.push({ ...record, reason });
    ignoredCounts[reason]++;
  } else {
    accepted.add(key);
    edges.push([pageIndex.get(record.source)!, pageIndex.get(record.destination)!, 1]);
  }
}
